@Test
void deletingSessionRemovesItsSearchProjection() throws Exception {
    var database = Files.createTempFile("ji-host-search-delete-", ".db");
    try (HostStore store = store(database)) {
        store.create("session-1", new ModelRef("profile", "model"), "workspace", NOW);
        SessionDocument named = store.update("session-1", 0,
                document -> document.setName(Optional.of("removable alpha")));
        assertFalse(store.search(HostStore.SearchQuery.firstPage("alpha")).hits().isEmpty());
        store.delete("session-1", named.revision());
        assertTrue(store.search(HostStore.SearchQuery.firstPage("alpha")).hits().isEmpty());
    }
}

